contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 depositAmount) public payable {
        require(address(this).balance >= depositAmount);
        c.fallback{value: depositAmount}();

        uint256 beforeBal = c.balances(address(this));
        uint256 beforeContractBal = address(c).balance;

        bool reverted;
        try c.withdraw() {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(
            reverted
                ? true
                : (c.balances(address(this)) == 0 && address(c).balance == beforeContractBal - beforeBal)
        );
    }

    receive() external payable {}
}

