contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount) public payable {
        require(amount > 0);
        require(amount <= msg.value);
        require(address(this).balance >= amount);

        uint cBalBefore = address(c).balance;
        uint senderBalBefore = c.balances(address(this));

        (bool sent, ) = address(c).call{value: amount}("");
        require(sent);

        uint cBalAfterDeposit = address(c).balance;
        uint senderBalAfterDeposit = c.balances(address(this));

        require(cBalAfterDeposit - cBalBefore == amount);
        require(senderBalAfterDeposit - senderBalBefore == amount);

        bool withdrawReverted;
        try c.withdraw() {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        assert(!withdrawReverted && address(c).balance == cBalBefore && c.balances(address(this)) == senderBalBefore);
    }

    receive() external payable {}
}

