contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount) public payable {
        require(amount > 0);
        require(address(this).balance >= amount);

        // Precondition: the sender has no prior balance in c
        require(c.balances(address(this)) == 0);

        // Deposit into c; target balance becomes amount
        (bool okDeposit, ) = address(c).call{value: amount}("");
        require(okDeposit);
        require(c.balances(address(this)) == amount);

        // Perform withdraw
        bool reverted;
        try c.withdraw() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: successful withdraw zeroes the balance
        assert(reverted || c.balances(address(this)) == 0);
    }

    receive() external payable {}
}

